mod dense;mod linear;mod pencil;mod tail;mod components;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn main(){counted::disable();components::controls();let old=include_str!("../native-public-2lp/CONTROL.txt");let mut calls=0;let mut failures=0;
 for line in include_str!("INSTANCES.tsv").lines().skip(1){let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let mut rng=Rng::new(2026111800^p^((g as u64)<<32));
 for case in 0..2{let sm=if case==0{1}else{17};let source=inst.curve.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let target=inst.curve.mul(&source,k);let seed=2026111800+case as u64;let prefix=format!("CASE g={g} p={p} c={cc} ell={ell} source_multiple={sm} case={case} seed={seed} expected={k} ");assert!(old.lines().any(|l|l.starts_with(&prefix)));eprintln!("start g={g} p={p} sm={sm} case={case}");let r=pencil::solve(&inst.curve,&source,&target,ell,512,true);let reference=include_str!("../native-pencil-2lp/CONTROL.txt");let exact=format!("CASE g={g} p={p} c={cc} ell={ell} sm={sm} case={case} expected={k} report={r:?}");assert!(reference.lines().any(|line|line==exact),"complete report changed");if let Some(answer)=r.k{assert_eq!(answer,k);assert_eq!(inst.curve.mul(&source,answer),target);}else{failures+=1;}println!("CASE g={g} p={p} c={cc} ell={ell} sm={sm} case={case} expected={k} report={r:?}");calls+=1;
 }}assert_eq!(calls,22);eprintln!("SUMMARY initial_models=11 exact_public_workloads={calls} failures={failures} every_queried_norm_and_known_root_product_exact=true every_queried_split_brute_checked=true every_accepted_principal_group_identity_checked=true dense_lp_prefix=true no_automorphism_or_log_oracle=true no_speed_claim=true");if failures>0{std::process::exit(2);}}
